/// An icon at `size` px, stroked with `currentColor` (themes may override via `.lucide`).
#[component]
pub fn Svg(
    icon: Icon,
    #[props(default = 24)] size: u32,
    #[props(default)] class: String,
) -> Element {
    rsx! {
        svg {
            class: "lucide {class}",
            xmlns: "http://www.w3.org/2000/svg",
            width: "{size}",
            height: "{size}",
            view_box: "0 0 24 24",
            fill: "none",
            stroke: "currentColor",
            stroke_width: "2",
            stroke_linecap: "round",
            stroke_linejoin: "round",
            "aria-hidden": "true",
            dangerous_inner_html: icon.body(),
        }
    }
}
